import{_ as a,o as l,a as n,b as p}from"./app.C41L12d5.js";const I=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"同步控制","link":"/api/SIMD-API/basic_api/sync_control/sync_control"},{"text":"核间同步","link":"/api/SIMD-API/basic_api/sync_control/inter_core_sync/inter_core_sync"},{"text":"CrossCoreWaitFlag(ISASI)","link":"/api/SIMD-API/basic_api/sync_control/inter_core_sync/CrossCoreWaitFlag_ISASI"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/sync_control/inter_core_sync/CrossCoreWaitFlag_ISASI.md","filePath":"api/SIMD-API/basic_api/sync_control/inter_core_sync/CrossCoreWaitFlag_ISASI.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":3,"title":"模板参数及输入参数说明","slug":"模板参数及输入参数说明","link":"#模板参数及输入参数说明"},{"level":3,"title":"模板参数默认值及生效情况","slug":"模板参数默认值及生效情况","link":"#模板参数默认值及生效情况"},{"level":3,"title":"modeId支持的取值说明","slug":"modeId支持的取值说明","link":"#modeId支持的取值说明"},{"level":3,"title":"flagId取值范围说明","slug":"flagId取值范围说明","link":"#flagId取值范围说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788180487000}'),t={name:"api/SIMD-API/basic_api/sync_control/inter_core_sync/CrossCoreWaitFlag_ISASI.md"};function e(c,s,d,i,o,r){return l(),n("div",null,[...s[0]||(s[0]=[p(`<div><article class="markdown-body"><h1>CrossCoreWaitFlag(ISASI)<a id="ZH-CN_TOPIC_0000001787470374"></a></h1><h2 id="产品支持情况">产品支持情况<a id="section1550532418810"></a><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a id="section618mcpsimp"></a><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_block_sync_intf.h&quot;</code>。</p><p>在核间同步场景中，CrossCoreSetFlag接口和CrossCoreWaitFlag接口配对工作，具体功能请参考<a href="CrossCoreSetFlag_ISASI.html#section618mcpsimp">CrossCoreSetFlag功能说明</a>。</p><h2 id="函数原型">函数原型<a id="section620mcpsimp"></a><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">modeId</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">PIPE_S</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">CrossCoreWaitFlag</span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">flagId</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a id="section622mcpsimp"></a><a class="header-anchor" href="#参数说明">​</a></h2><h3 id="模板参数及输入参数说明">模板参数及输入参数说明<a class="header-anchor" href="#模板参数及输入参数说明">​</a></h3><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>modeId</td><td>核间同步的模式，默认值为0。不同产品对该参数的生效情况及支持的流水类型请参见<a href="#template-parameter-defaults">模板参数默认值及生效情况</a>。<br>不同产品对同步模式的支持情况请参见<a href="#modeId%E6%94%AF%E6%8C%81%E7%9A%84%E5%8F%96%E5%80%BC%E8%AF%B4%E6%98%8E">modeId支持的取值说明</a>。<br>各个模式支持的对应核函数（Kernel）类型请参照<a href="#table3">表3</a>。</td></tr><tr><td>pipe</td><td>设置该接口阻塞的流水类型，默认值为PIPE_S。不同产品对该参数的生效情况及支持的流水类型请参见<a href="#template-parameter-defaults">模板参数默认值及生效情况</a>。</td></tr></tbody></table><h3 id="模板参数默认值及生效情况">模板参数默认值及生效情况<a id="template-parameter-defaults"></a><a class="header-anchor" href="#模板参数默认值及生效情况">​</a></h3><div data-filter="950"><ul><li><p>针对Ascend 950PR/Ascend 950DT，两个模板参数的使用描述如下：</p><ul><li>modeId <ul><li><code>modeId</code>不直接作为硬件指令的输入，CrossCoreWaitFlag会根据该参数选择对应的硬件指令。</li><li>模式0、模式1和模式2使用相同的硬件指令。省略<code>modeId</code>时使用默认值<code>0</code>，不影响接口功能；但<strong>建议显式传入与CrossCoreSetFlag相同的<code>modeId</code></strong>，便于确认两个接口的同步模式匹配。</li><li>模式4使用的硬件指令与模式0、模式1和模式2不同，<strong>必须显式传入<code>modeId=4</code></strong>，否则接口会按照默认的模式0执行，导致同步行为不符合预期。</li></ul></li><li>pipe <ul><li><code>pipe</code>作为硬件指令的输入，参数取值<strong>生效</strong>，用于指定CrossCoreWaitFlag阻塞的流水。</li><li>省略<code>pipe</code>时使用默认值<code>PIPE_S</code>。</li><li>模式0、模式1、模式2和模式4支持<code>PIPE_S</code>、<code>PIPE_V</code>、<code>PIPE_M</code>、<code>PIPE_MTE1</code>、<code>PIPE_MTE2</code>、<code>PIPE_MTE3</code>、<code>PIPE_FIX</code>，不支持<code>PIPE_ALL</code>。</li></ul></li></ul></li></ul></div><div data-filter="A3,910b"><ul><li><p>针对如下产品，<strong>参数取值不影响硬件指令功能</strong>，两个模板参数的使用描述如下：</p><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div><p><code>modeId</code>和<code>pipe</code>均不作为硬件指令的输入，建议按如下方式配置：</p><ul><li>modeId：省略该参数不影响接口功能；但<strong>建议显式传入与CrossCoreSetFlag相同的<code>modeId</code></strong>，便于确认两个接口的同步模式匹配。</li><li>pipe：<strong>建议省略该参数并使用默认值<code>PIPE_S</code></strong>。无论<code>pipe</code>取值为何，CrossCoreWaitFlag都会阻塞<strong>全部流水</strong>的后续指令。</li></ul></li></ul></div><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>flagId</td><td>输入</td><td>核间同步的标记。不同产品对flagId的取值范围说明请参见<a href="#flagId%E5%8F%96%E5%80%BC%E8%8C%83%E5%9B%B4%E8%AF%B4%E6%98%8E">flagId取值范围说明</a>。</td></tr></tbody></table><h3 id="modeId支持的取值说明">modeId支持的取值说明<a id="modeId支持的取值说明"></a><a class="header-anchor" href="#modeId支持的取值说明">​</a></h3><p>不同产品对同步模式的支持情况如下：</p><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，支持的同步模式为：模式0、模式1、模式2、模式4。</li></ul></div><div data-filter="A3,910b"><ul><li>针对如下产品，支持的同步模式为：模式0、模式1、模式2。 <div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div></li></ul></div><h3 id="flagId取值范围说明">flagId取值范围说明<a id="flagId取值范围说明"></a><a class="header-anchor" href="#flagId取值范围说明">​</a></h3><ul><li>核间同步的模式为模式0、1、2时，支持的取值范围为0-15。</li></ul><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，核间同步的模式为模式4时，支持的取值范围情况如下： <ul><li>AIV0发起的flagId 0-15的CrossCoreSetFlag操作对应AIC CrossCoreWaitFlag中flagId 0-15的操作。</li><li>AIV1发起的flagId 0-15的CrossCoreSetFlag操作对应AIC CrossCoreWaitFlag中flagId 16-31的操作。</li><li>AIC发起的flagId 0-15的CrossCoreSetFlag操作对应AIV0 CrossCoreWaitFlag中flagId 0-15的操作。</li><li>AIC发起的flagId 16-31的CrossCoreSetFlag操作对应AIV1 CrossCoreWaitFlag中flagId 0-15的操作。</li></ul></li></ul></div><p>此外，当与Matmul高阶API或SyncAll接口同时使用时，开发者自行使用的flagId还需注意避免与这些接口内部已占用的flagId冲突，详见<a href="#flagId%E5%86%B2%E7%AA%81%E8%AF%B4%E6%98%8E">约束说明</a>中的flagId占用情况。</p><h2 id="返回值说明">返回值说明<a id="section640mcpsimp"></a><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a id="section633mcpsimp"></a><a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>由于当核函数（Kernel）类型为KERNEL_TYPE_AIC_ONLY或KERNEL_TYPE_AIV_ONLY时，硬件不会开启调度模块，也就无法正常进行核间同步，因此不同的同步模式配置<a href="../../Kernel-Tiling/set_Kernel_type.html">核函数（Kernel）类型</a>或<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#section1074418132518">函数修饰符</a>的情况如下：</p><ul><li><p>在纯Vector/Cube场景下（模式0或模式1），建议设置核函数（Kernel）类型为KERNEL_TYPE_MIX_AIV_1_0或KERNEL_TYPE_MIX_AIC_1_0，其它支持的核函数（Kernel）类型请参考表3。</p></li><li><p>对于Vector和Cube混合场景（模式2和模式4），需根据AI Core中AIC和AIV的比例灵活配置核函数（Kernel）类型，不同模式支持的函数修饰符和核函数（Kernel）类型请参照表3。</p><p><strong>表3</strong> 模式与支持的核函数（Kernel）类型配置<a id="table3"></a></p><table><thead><tr><th>模式</th><th>支持的函数修饰符</th><th>支持的核函数（Kernel）类型配置</th></tr></thead><tbody><tr><td>0</td><td>__mix__(0, 1)、__mix__(1, 0)、__mix__(1, 1)、__mix__(1, 2)</td><td>KERNEL_TYPE_MIX_AIV_1_0、KERNEL_TYPE_MIX_AIC_1_0、KERNEL_TYPE_MIX_AIC_1_1、KERNEL_TYPE_MIX_AIC_1_2</td></tr><tr><td>1</td><td>__mix__(1, 1)、__mix__(1, 2)</td><td>KERNEL_TYPE_MIX_AIC_1_1、KERNEL_TYPE_MIX_AIC_1_2</td></tr><tr><td>2</td><td>__mix__(1, 1)、__mix__(1, 2)</td><td>KERNEL_TYPE_MIX_AIC_1_1、KERNEL_TYPE_MIX_AIC_1_2</td></tr><tr><td>4</td><td>__mix__(1, 2)</td><td>KERNEL_TYPE_MIX_AIC_1_2</td></tr></tbody></table></li></ul></li><li><p>CrossCoreWaitFlag必须与<a href="CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>接口配合使用，避免计算核一直处于阻塞阶段。建议显式配置与配对CrossCoreSetFlag相同的modeId，以便确认Set与Wait使用相同的同步模式。</p></li></ul><p><a id="flagId冲突说明"></a></p><ul><li><p>以下接口内部实现中使用了CrossCoreSetFlag和CrossCoreWaitFlag会占用一部分flagId，开发者同时使用CrossCoreSetFlag/CrossCoreWaitFlag与以下接口时，需注意避免flagId使用冲突：</p><ul><li>Matmul高阶API占用的flagId范围与定义的Matmul对象数目相关，假设定义了N个Matmul对象，Matmul高阶API内部占用的flagId范围为[0, 2 * N - 1]。Matmul最多支持定义4个对象，此时flagId占用范围为[0,7]。</li><li>SyncAll硬件同步接口占用的flagId情况请参考<a href="SyncAll.html#syncall_flagId%E5%86%B2%E7%AA%81%E8%AF%B4%E6%98%8E">flagId占用情况</a>。</li></ul></li><li><p>flagId相关的约束：</p><ul><li>对于模式0、1、2，每个AIC和每个AIV都各自有16个flagId，支持的取值范围为0-15。如果flagId的值超出该范围，则截取低4bit（例如，flagId=17时，截取后为1）。</li></ul><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，核间同步的模式为模式4时，AIC有32个flagId，支持的取值范围为0-31，如果flagId的值超出该范围，则截取低5bit（例如，flagId=35时，截取后为3）；AIV有16个flagId，支持的取值范围为0-15，如果flagId的值超出该范围，则截取低4bit（例如，flagId=17时，截取后为1）。</li></ul></div><ul><li>每个flagId都对应一个计数器，当调用<a href="CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a>时，若计数器值为0则会阻塞后续指令下发，已下发指令可正常执行；当调度模块感知到核间同步（CrossCoreSetFlag）全部完成后，会将对应CrossCoreWaitFlag的计数器的值增加1。此时，计数器值为非0，阻塞解除，并且将对应计数器的值减去1进行还原。具体执行逻辑与细节可以参考<a href="key_features.html#ZH-CN_TOPIC_0000002586300741">关键特性说明</a>。flagId对应的计数器计数范围为0-15。如果计数器的值超出该范围，则会异常报错，中断流程。</li></ul></li><li><p>模式0、1、2下，同一个flagId用于不同核间同步模式的约束：</p><ul><li>同一核上，若同一个flagId需用于不同核间同步模式，须在模式切换前完成前一个模式的所有同步操作——即确保该flagId关联的所有CrossCoreSetFlag与配套CrossCoreWaitFlag调用均已执行完毕。</li><li>对于不同的核，可以直接将同一flagId用于不同的核间同步模式，具体包括以下2种场景： <ul><li>多个AI Core之间，使用flagId=0同步所有的AIC（模式0）；单个AI Core内，使用flagId=0同步所有AIV（模式1）。</li><li>单个AI Core内，使用flagId=0同步所有AIV（模式1）；另一个AI Core内，使用flagId=0同步AIC与所有AIV（模式2）。</li></ul></li></ul></li><li><p>使用该接口模式0时，建议开启batchmode模式，使算子独占全部所需核资源，否则可能因满足以下条件导致死锁：</p><ul><li>多流并发场景（≥2条执行流）。</li><li>≥2个算子并发执行。</li><li>所有并发算子的核数总和超过物理核数。</li><li>≥2个并发算子使用了核间同步功能。</li></ul><p>具体而言，在多流场景下，某条流的核间同步算子虽分配到n个物理核，但可能仅有n-m个核先被调度执行，而其余m个核因被其他流的核间同步算子抢占而尚未启动。先启动的n-m个核执行到核间同步时等待剩余m核完成，而剩余m核因被其他流的核间同步算子占用而无法释放，形成死锁。</p><p>核函数（Kernel）直调场景下通过<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">__schedmode__(mode)</a>限定符来设置batchmode模式；工程化算子开发场景下，通过TilingContext的SetScheduleMode接口来设置batchmode模式，具体请参考《<a href="https://gitcode.com/cann/metadef/blob/master/docs/zh/api/README.md">基础数据结构和接口</a>》。</p></li></ul><h2 id="调用示例">调用示例<a id="section837496171220"></a><a class="header-anchor" href="#调用示例">​</a></h2><p><strong>表4</strong> 样例描述</p><table><thead><tr><th>SCENARIO_NUM取值</th><th>业务场景</th><th>使用的同步模式</th></tr></thead><tbody><tr><td>0</td><td>纯Vector计算场景（16个AIV）</td><td>mode0（AIV全核同步）</td></tr><tr><td>1</td><td>纯Vector计算场景（2个AIV）</td><td>mode1</td></tr><tr><td>2</td><td>Cube与Vector融合计算场景</td><td>mode2（AIC等AIV）、mode2（AIV等AIC）、mode0（AIC全核同步）</td></tr></tbody></table><p>如上表所示，当SCENARIO_NUM取不同值时，会分别演示纯Vector计算场景和Cube与Vector融合计算场景下三种同步模式的具体使用方法，下面展示了纯Vector计算场景的部分调用代码：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Muls</span><span class="p">(</span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">()),</span><span class="w"> </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">SetFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">V_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">WaitFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">V_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="n">EVENT_ID0</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// Unified Buffer（UB）到GM搬运启用原子累加。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">SetAtomicAdd</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="c1">// DataCopy属于PIPE_MTE3流水操作。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">atomicResultGm</span><span class="p">,</span><span class="w"> </span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 当本AIV完成前置PIPE_MTE3(DataCopy)流水操作后，通知其他AIV核，本AIV已经完成。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreSetFlag</span><span class="o">&lt;</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 阻塞本AIV继续往下执行指令，直到其他AIV全部都完成PIPE_MTE3流水操作，才解除阻塞往下执行。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreWaitFlag</span><span class="o">&lt;</span><span class="mi">0</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 关闭原子累加。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DisableDmaAtomic</span><span class="p">();</span>

<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">()</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">atomicResultGm</span><span class="p">,</span><span class="w"> </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">SetFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">MTE2_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">WaitFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">MTE2_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">atomicResultGm</span><span class="p">,</span><span class="w"> </span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">        </span><span class="k">return</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
</code></pre></div><p>完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/05_sync_control/cross_core_set_wait_flag">CrossCoreSetFlag和CrossCoreWaitFlag核间同步样例</a>。</p></article></div>`,1)])])}const g=a(t,[["render",e]]);export{I as __pageData,g as default};
